CREATE DATABASE IF NOT EXISTS library_auth;
CREATE DATABASE IF NOT EXISTS library_books;
USE library_auth;
CREATE TABLE IF NOT EXISTS users (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('USER','ADMIN') NOT NULL DEFAULT 'USER', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
USE library_books;
CREATE TABLE IF NOT EXISTS books (id INT NOT NULL AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, author VARCHAR(255) NOT NULL, isbn VARCHAR(20) NOT NULL UNIQUE, category VARCHAR(100) NULL, description TEXT NULL, total_copies INT NOT NULL DEFAULT 0, available_copies INT NOT NULL DEFAULT 0);
